#!/usr/bin/env bash
# Generated by scripts/generate_split_core_sim.py; edit the generator.
set -euo pipefail
SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
KVIP_ROOT="${KVIP_ROOT:-$(cd -- "$SCRIPT_DIR/../.." && pwd)}"
for arg in "$@"; do
    case "$arg" in
        --backend|--backend=*|--suite|--suite=*)
            printf '%s\n' 'Generated entry fixes Model backend and suite; use the Python CLI for native' >&2
            exit 2 ;;
    esac
done
KVIP_ACTION="${KVIP_ACTION:-run}"
KVIP_PYTHON="${KVIP_PYTHON:-python3}"
KVIP_BUDGET="${KVIP_BUDGET:-28/56}"
KVIP_TOPK_SHARDS="${KVIP_TOPK_SHARDS:-1}"
KVIP_HEADS="${KVIP_HEADS:-32}"
KVIP_OUTPUT="${KVIP_OUTPUT:-$KVIP_ROOT/tests/results/split-smoke-$(date -u +%Y%m%dT%H%M%S)-$$}"
if [[ -n "${KVIP_SIM_LEASE_FILE:-}" ]]; then
    set -- --lease-file "$KVIP_SIM_LEASE_FILE" "$@"
fi
if [[ "$KVIP_ACTION" == run ]]; then
    ASCEND_HOME_PATH="${ASCEND_HOME_PATH:-/usr/local/Ascend/cann}"
    if [[ -z "${KVIP_CANN_ARCH:-}" ]]; then
        case "$(uname -m)" in
            aarch64|arm64) KVIP_CANN_ARCH=aarch64-linux ;;
            x86_64) KVIP_CANN_ARCH=x86_64-linux ;;
            *) printf '%s\n' 'Set KVIP_CANN_ARCH for this CANN installation' >&2; exit 2 ;;
        esac
    fi
    model_lib="$ASCEND_HOME_PATH/$KVIP_CANN_ARCH/simulator/dav_3510/lib"
    if [[ ! -f "$model_lib/libruntime_camodel.so" ]]; then
        printf '%s\n' "Missing CANN Model runtime: $model_lib/libruntime_camodel.so" >&2
        exit 2
    fi
    if [[ -z "${KVIP_MODEL_DRIVER:-}" ]]; then
        KVIP_BUILD_DIR="${KVIP_BUILD_DIR:-$KVIP_ROOT/build/split-topk}"
        cmake -S "$KVIP_ROOT/csrc/operators/split_topk" -B "$KVIP_BUILD_DIR" \
            -DRUN_MODE=sim "-DSOC_VERSION=${KVIP_SOC:-Ascend950PR_9599}" \
            "-DASCEND_CANN_PACKAGE_PATH=$ASCEND_HOME_PATH"
        cmake --build "$KVIP_BUILD_DIR" --target topk_sim -j "${KVIP_BUILD_JOBS:-2}"
        KVIP_MODEL_DRIVER="$KVIP_BUILD_DIR/topk_sim"
    fi
    export LD_LIBRARY_PATH="$model_lib:$ASCEND_HOME_PATH/$KVIP_CANN_ARCH/lib64:$ASCEND_HOME_PATH/$KVIP_CANN_ARCH/devlib${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
    export LD_PRELOAD="$model_lib/libruntime_camodel.so${LD_PRELOAD:+:$LD_PRELOAD}"
    set -- --model-driver "$KVIP_MODEL_DRIVER" "$@"
fi
exec "$KVIP_PYTHON" "$KVIP_ROOT/scripts/run_split_core_cases.py" "$KVIP_ACTION" \
    --backend model --suite smoke --group all --budget "$KVIP_BUDGET" \
    --shards "$KVIP_TOPK_SHARDS" --heads "$KVIP_HEADS" --output "$KVIP_OUTPUT" \
    "$@"
